practice.solution:
def re_match(r, s):
    pos = [0]
    def peek():
        if pos[0] < len(r):
            return r[pos[0]]
        return ''
    def expr():
        left = term()
        while peek() == '+':
            pos[0] += 1
            right = term()
            left = ('u', left, right)
        return left
    def term():
        node = ('e',)
        while peek() != '' and peek() != '+' and peek() != ')':
            f = factor()
            node = ('c', node, f)
        return node
    def factor():
        a = atom()
        while peek() == '*':
            pos[0] += 1
            a = ('s', a)
        return a
    def atom():
        c = peek()
        pos[0] += 1
        if c == '(':
            n = expr()
            pos[0] += 1
            return n
        return ('l', c)
    tree = expr()
    def ends(node, i):
        k = node[0]
        if k == 'e':
            return [i]
        if k == 'l':
            if i < len(s) and s[i] == node[1]:
                return [i + 1]
            return []
        if k == 'u':
            out = ends(node[1], i)
            for e in ends(node[2], i):
                if e not in out:
                    out.append(e)
            return out
        if k == 'c':
            out = []
            for j in ends(node[1], i):
                for e in ends(node[2], j):
                    if e not in out:
                        out.append(e)
            return out
        seen = [i]
        todo = [i]
        while todo:
            j = todo.pop()
            for e in ends(node[1], j):
                if e not in seen:
                    seen.append(e)
                    todo.append(e)
        return seen
    return len(s) in ends(tree, 0)

