def cfg_generate(rules, maxlen):
    cap = maxlen + 4
    seen = set(['S'])
    todo = ['S']
    words = set()
    while todo:
        form = todo.pop()
        idx = -1
        for i in range(len(form)):
            if form[i].isupper():
                idx = i
                break
        if idx == -1:
            if len(form) <= maxlen:
                words.add(form)
            continue
        for r in rules:
            if r[0] == form[idx]:
                new = form[:idx] + r[1] + form[idx + 1:]
                if len(new) <= cap and new not in seen:
                    seen.add(new)
                    todo.append(new)
    out = list(words)
    out.sort()
    return out

