def run_assign(program, var):
    mem = {}
    def val(tok):
        if tok.lstrip('-').isdigit():
            return int(tok)
        return mem.get(tok, 0)
    for line in program:
        parts = line.split('=')
        name = parts[0].strip()
        right = parts[1].strip().split()
        if len(right) == 3:
            a = val(right[0])
            b = val(right[2])
            if right[1] == '+':
                mem[name] = a + b
            else:
                mem[name] = a - b
        else:
            mem[name] = val(right[0])
    return mem.get(var, 0)

