practice.solution:
def chomsky_class(rules):
    def single(l):
        return len(l) == 1 and l.isupper()
    def linear(r):
        if r == '':
            return True
        i = 0
        while i < len(r) and not r[i].isupper():
            i += 1
        if i == len(r):
            return True
        return i == len(r) - 1
    ok3 = True
    ok2 = True
    ok1 = True
    for r in rules:
        l = r[0]
        rhs = r[1]
        if not (single(l) and linear(rhs)):
            ok3 = False
        if not single(l):
            ok2 = False
        if len(rhs) < len(l):
            ok1 = False
    if ok3:
        return 3
    if ok2:
        return 2
    if ok1:
        return 1
    return 0

