practice.solution:
def run_tm(machine, tape, max_steps):
    nstates = machine[0]
    nsyms = machine[1]
    nhalt = machine[2]
    delta = {}
    for t in machine[3]:
        delta[(t[0], t[1])] = (t[2], t[3], t[4])
    cells = {}
    for i in range(len(tape)):
        cells[i] = tape[i]
    state = 0
    head = 0
    steps = 0
    while state < nstates - nhalt:
        if steps >= max_steps:
            return [-1, state, []]
        key = (state, cells.get(head, nsyms))
        if key not in delta:
            return [-2, state, []]
        nxt = delta[key]
        state = nxt[0]
        cells[head] = nxt[1]
        if nxt[2] == 'R':
            head += 1
        else:
            head -= 1
        steps += 1
    if not cells:
        return [steps, state, []]
    out = []
    for i in range(min(cells), max(cells) + 1):
        out.append(cells.get(i, nsyms))
    while out and out[-1] == nsyms:
        out.pop()
    while out and out[0] == nsyms:
        out.pop(0)
    return [steps, state, out]

