def sat_brute(clauses, n):
    for m in range(2 ** n):
        assign = []
        for i in range(n):
            assign.append((m >> i) & 1)
        good = True
        for cl in clauses:
            ok = False
            for lit in cl:
                v = assign[abs(lit) - 1]
                if (lit > 0 and v == 1) or (lit < 0 and v == 0):
                    ok = True
                    break
            if not ok:
                good = False
                break
        if good:
            return assign
    return []

