import math
def empirical_entropy(s):
    n = len(s)
    if n == 0:
        return 0.0
    counts = {}
    for c in s:
        counts[c] = counts.get(c, 0) + 1
    total = 0.0
    for c in counts:
        p = counts[c] / n
        total -= p * math.log(p) / math.log(2)
    return total

