def description_bound(s):
    if len(s) == 0:
        return 0
    cost = 0
    i = 0
    while i < len(s):
        j = i
        while j < len(s) and s[j] == s[i]:
            j += 1
        cost += 1 + len(str(j - i))
        i = j
    return min(len(s), cost)
